"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { useToast } from "../../components/ToastContext";
import { apiFetch } from "@/lib/api";

export default function MapColumnsPage() {
  const router = useRouter();
  const { showToast } = useToast();

  const [columns, setColumns] = useState<string[]>([]);
  const [mapping, setMapping] = useState({
    supplier: "",
    sku: "",
    delay_days: "",
    cost: "",
  });

  useEffect(() => {
    apiFetch(`/upload/columns`)
      .then((res) => {
        if (!res.ok) throw new Error("Failed to fetch columns");
        return res.json();
      })
      .then((data) => setColumns(data.columns))
      .catch(() => {
        showToast("Could not load columns. Is the backend running?", "error");
      });
  }, [showToast]);

  const handleSubmit = async () => {
    if (Object.values(mapping).some((v) => !v)) {
      showToast("Please map all fields before confirming.", "warning");
      return;
    }

    try {
      await apiFetch(`/upload/confirm`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(mapping),
      });
      router.push("/dashboard");
    } catch {
      showToast("Failed to confirm mapping.", "error");
    }
  };

  return (
    <main
      style={{
        minHeight: "100vh",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: "#0e1116",
        color: "#fff",
        fontFamily: "var(--font-sans)",
      }}
    >
      <div
        style={{
          width: "100%",
          maxWidth: 500,
          border: "1px solid rgba(255,255,255,0.15)",
          borderRadius: 16,
          padding: 32,
        }}
      >
        <h1 style={{ fontSize: 24, fontWeight: 600, marginBottom: 24 }}>
          Map Your CSV Columns
        </h1>

        {(["supplier", "sku", "delay_days", "cost"] as const).map((field) => (
          <div key={field} style={{ marginBottom: 16 }}>
            <label
              style={{
                display: "block",
                marginBottom: 8,
                fontSize: 12,
                opacity: 0.7,
                textTransform: "uppercase",
                letterSpacing: "0.08em",
              }}
            >
              {field.toUpperCase()}
            </label>
            <select
              style={{
                width: "100%",
                background: "#000",
                border: "1px solid rgba(255,255,255,0.2)",
                padding: "10px 12px",
                borderRadius: 8,
                color: "#fff",
                fontSize: 14,
                outline: "none",
              }}
              onChange={(e) =>
                setMapping({ ...mapping, [field]: e.target.value })
              }
            >
              <option value="">Select column</option>
              {columns.map((col) => (
                <option key={col} value={col}>
                  {col}
                </option>
              ))}
            </select>
          </div>
        ))}

        <button
          onClick={handleSubmit}
          style={{
            marginTop: 24,
            width: "100%",
            background: "var(--color-accent, #06b6d4)",
            color: "#000",
            padding: "14px",
            borderRadius: 10,
            fontWeight: 600,
            fontSize: 14,
            border: "none",
            cursor: "pointer",
          }}
        >
          Confirm &amp; Analyze
        </button>
      </div>
    </main>
  );
}
